// Exercise both Write overloads using random choice, honoring buffer readability and size constraints.
// Input 'out' is an abstract sink; we only use its virtual API and do not destroy it.
std::string src = FUZZ_PARAM_STR();
const uint8_t* buf = reinterpret_cast<const uint8_t*>(src.data());
size_t src_len = src.size();
// Keep writes modest for fuzzer performance
size_t cap = src_len < 1024 ? src_len : (size_t)1024;
unsigned choice = *FUZZ_PARAM(unsigned int);
if ((choice & 1u) == 0u) {
    // Append form: choose n within [0, cap]
    size_t n = (cap == 0) ? 0 : ((size_t)(*FUZZ_PARAM(unsigned int)) % (cap + 1));
    // If n > 0, 'buf' points to at least n bytes due to cap
    bool ok = out->Write(buf, n);
    (void)ok; // Allowed to fail depending on implementation limits
} else {
    // Random-access form: choose offset and n, with n within [0, cap], and offset biased to current Size()
    size_t n = (cap == 0) ? 0 : ((size_t)(*FUZZ_PARAM(unsigned int)) % (cap + 1));
    size_t cur = out->Size();
    // Bias offset to be near current size; still may exceed implementation limits which is fine
    size_t off_bias = cur + ((size_t)(*FUZZ_PARAM(unsigned int)) % (size_t)256);
    size_t offset = (choice & 2u) ? (off_bias) : ((size_t)(*FUZZ_PARAM(unsigned int)) % (cur + 1));
    bool ok = out->Write(buf, offset, n);
    (void)ok;
}
// Track observed size for downstream stubs
FUZZ_SET_ATTR_INT(out, "size", (int)out->Size());

// Query and record the current logical size. No side effects on ownership.
size_t sz = out->Size();
FUZZ_SET_ATTR_INT(out, "size", (int)sz);
(void)sz;

