    params.extended_metadata = meta;
    params.brotli_quality = (int)(*FUZZ_PARAM(unsigned int) % 12); // commonly 0..11
    params.allow_transforms = ((*FUZZ_PARAM(unsigned int) & 1u) != 0u);
    // Recompute a bound aware of metadata, still cap to 2048
    size_t est_meta = woff2::MaxWOFF2CompressedSize(in_data, in_len, params.extended_metadata);
    size_t cap2 = est_meta > (size_t)2048 ? (size_t)2048 : est_meta;
    if (cap2 == 0) cap2 = (size_t)1;
    buf.assign(cap2, 0);
    out_len = cap2;
    bool ok = woff2::ConvertTTFToWOFF2(in_data, in_len, buf.data(), &out_len, params);
    (void)ok;
}

